+// Tiny client-side include: swaps any element with `data-include` with fetched HTML.
+// Keeps this site build-step-free while avoiding duplicated nav/footer markup.
+(function () {
+  async function hydrateIncludes() {
+    const nodes = Array.from(document.querySelectorAll('[data-include]'));
+    await Promise.all(
+      nodes.map(async (el) => {
+        const path = el.getAttribute('data-include');
+        if (!path) return;
+        try {
+          const res = await fetch(path, { cache: 'no-cache' });
+          if (!res.ok) throw new Error('HTTP ' + res.status);
+          const html = await res.text();
+          el.outerHTML = html;
+        } catch (e) {
+          // If fetch fails (file:// restrictions), fall back to no-op.
+          // Pages still render; nav will be missing.
+          // Users can run a local static server for full fidelity.
+          console.warn('Include failed:', path, e);
+        }
+      })
+    );
+  }
+
+  if (document.readyState === 'loading') {
+    document.addEventListener('DOMContentLoaded', hydrateIncludes);
+  } else {
+    hydrateIncludes();
+  }
